let fileName = "";

// 1. まず '未処理写真の抽出と件数制限'（ループ前のノード）から直接ファイル名を取得してみる
try {
    fileName = $('未処理写真の抽出と件数制限').item.json.fileName || "";
} catch(e) {}

// 2. もし取得できなかった場合のバックアップ（filePathからファイル名部分を自動で切り出す）
if (!fileName) {
    let filePath = "";
    try {
        filePath = $('未処理写真の抽出と件数制限').item.json.filePath || "";
    } catch(e) {}

    if (!filePath) {
        try {
            filePath = $('画像ファイルの読み込み').item.json.filePath || "";
        } catch(e) {}
    }

    // フルパスからファイル名（末尾）だけを切り分ける
    if (filePath) {
        fileName = filePath.split('/').pop().split('\\').pop();
    }
}

// 3. ファイル名 + 改行コードをセット
const content = fileName ? (fileName + "\n") : "";

const binaryData = await this.helpers.prepareBinaryData(
    Buffer.from(content, 'utf8'),
    'processed.txt',
    'text/plain'
);

return [{
    json: { fileName: fileName, logged: !!fileName },
    binary: { fileContent: binaryData }
}];

const BASE_PATH = "/home/node/.n8n-files/picture";

// 1. 処理済みログテキスト化 ノードから、完全にテキスト化した processed.txt の中身を取得する
let processedText = "";
try {
    processedText = $('処理済みログテキスト化').first().json.data || "";
} catch (e) {
    processedText = "";
    console.log("processed.txtのテキスト化データが見つかりませんでした");
}

// 2. processed.txt の中身からファイル名だけを切り出し、小文字にして Set に登録
const processedFiles = new Set(
    processedText
        .split(/\r?\n|\\n/)
        .map(line => line.trim())
        .filter(line => line !== "")
        .map(line => line.split('/').pop().split('\\').pop().toLowerCase())
);

// 3. 全ファイルリストを処理
const allInputItems = $input.all();
const todoFiles = [];

for (const item of allInputItems) {
    // ★【重要修正】バイナリメタデータからファイル情報を取得する
    // item.json ではなく item.binary.data に fileName や directory が格納されている
    const binData = (item.binary && item.binary.data) ? item.binary.data : {};

    const name = binData.fileName              // ← バイナリメタデータの File Name
              || item.json["fileName"]         // ← 念のため JSON も確認
              || item.json["File Name"]
              || item.json["name"]
              || "";

    if (!name || name === "processed.txt") continue;

    // 比較用にファイル名を小文字に変換
    const lowerName = name.trim().toLowerCase();

    // ★ファイル名のみで照合して、既に処理済みならスキップ！
    if (processedFiles.has(lowerName)) {
        continue;
    }

    // ★【重要修正】実在する正しいディレクトリをバイナリメタデータから取得
    const actualDir = binData.directory || "";  // ← バイナリメタデータの Directory

    let filePath = "";
    let dirPath = "";

    if (actualDir) {
        // バイナリメタデータに実在するディレクトリがあれば、それを使う（最も確実）
        dirPath = actualDir;
        filePath = `${dirPath}/${name}`;
    } else if (item.json["filePath"]) {
        // JSON に filePath があればそのまま使う
        filePath = item.json["filePath"];
        dirPath = filePath.substring(0, filePath.lastIndexOf('/'));
    } else {
        // 最終フォールバック: ファイル名から日付フォルダを推測
        dirPath = BASE_PATH;
        const dateMatch = name.match(/^(\d{4})(\d{2})\d{2}/);
        if (dateMatch) {
            const year = dateMatch[1];
            const month = dateMatch[2];
            dirPath = `${BASE_PATH}/${year}/${year}-${month}`;
        }
        filePath = `${dirPath}/${name}`;
    }

    todoFiles.push({
        json: { filePath, fileName: name, directory: dirPath }
    });
}

// 4. 終了判定とバッチ処理
if (todoFiles.length === 0) {
    return [{ json: {
        message: "未処理の写真はありませんでした。",
        処理済み件数: processedFiles.size
    }}];
}

const dailyLimit = 500;
const batch = todoFiles.slice(0, dailyLimit);
console.log(`未処理合計: ${todoFiles.length}件 → 本日処理分: ${batch.length}件`);

return batch;

// ★画像ファイルの読み込みノードからバイナリメタデータを直接取得
const imageNodeItem = $('画像ファイルの読み込み').first();
const binData = imageNodeItem.binary?.data || {};
const jsonData = $input.first().json || {};

// バイナリメタデータからファイル情報を取得
let fileName = binData.fileName || "";
let filePath = binData.directory 
    ? `${binData.directory}/${fileName}` 
    : "";

// 念のためJSONからも取得を試みる
if (!fileName) {
    fileName = jsonData.fileName || "";
    filePath = jsonData.filePath || "";
}

// Gemini の判定理由を取得
let reason = "";
try {
    const text = jsonData.content?.parts?.[0]?.text || "";
    const parsed = JSON.parse(text);
    reason = parsed.reason || "";
} catch (e) {}

// ★画像ファイルでない場合はスキップ（空のアイテムを返す）
if (!fileName || !/\.(jpg|jpeg|png|gif|bmp|webp)$/i.test(fileName)) {
    return [{ json: { 
        "ファイル名": "", 
        "Windowsパス": "", 
        "判定理由": "", 
        "リンクURL": "" 
    }}];
}

const windowsPath = filePath
    .replace('/home/node/.n8n-files/picture', 'D:\\Pictures')
    .replace(/\//g, '\\');

// ★修正箇所：各行番号に応じたHYPERLINK関数を生成
const results = [];
const items = $input.all(); // 全アイテムを取得

for (let i = 0; i < items.length; i++) {
    // Excelの行番号は2行目から始まる（ヘッダー行が1行目）
    const excelRow = i + 2;

    // リンクURLにHYPERLINK関数を設定（D列のセルを参照）
    const hyperlinkFunction = `=HYPERLINK(B${excelRow})`;

    results.push({
        json: {
            "ファイル名": fileName,
            "Windowsパス": windowsPath,
            "判定理由": reason,
            "リンクURL": hyperlinkFunction
        }
    });
}

return results;
